<template><section class="shared-files"><h3>Shared files & enrollment copies</h3><p v-if="loading">Loading files…</p><p v-if="error" role="alert">{{error}}</p><p v-if="!loading&&!error&&!files.length">No additional files have been shared yet. Paper enrollment copies will appear here when the care team shares them.</p><article v-for="f in files" :key="f.id"><div><strong>{{f.title}}</strong><small>Shared {{new Date(f.sharedAt).toLocaleDateString()}}</small></div><button :disabled="busy" @click="download(f)">Download copy</button></article></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {usePortalCareApi} from '../../composables/usePortalCareApi';
const api=usePortalCareApi();
const props=defineProps({clientId:[Number,String]});const files=ref([]),loading=ref(false),busy=ref(false),error=ref('');let seq=0;
async function load(){const own=++seq;files.value=[];error.value='';if(!props.clientId)return;loading.value=true;try{const{data}=await api.get(`/guardian-portal/clients/${props.clientId}/shared-files`);if(own===seq)files.value=data.files||[];}catch(e){if(own===seq)error.value=e.response?.status===403?'Shared chart files are not available with your current document permissions.':'Shared files could not be loaded.';}finally{if(own===seq)loading.value=false;}}
async function download(f){const own=seq;busy.value=true;error.value='';try{const{data}=await api.get(`/guardian-portal/clients/${props.clientId}/shared-files/${f.id}`,{responseType:'blob'});if(own!==seq)return;const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=f.title.replace(/[^a-z0-9 ._-]/gi,'')+(/\.[a-z0-9]{2,5}$/i.test(f.title)?'':({'application/pdf':'.pdf','image/png':'.png','image/jpeg':'.jpg','text/plain':'.txt'}[f.mimeType]||''));a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{if(own===seq)error.value='This copy could not be downloaded. Refresh and try again.';}finally{busy.value=false;}}
watch(()=>props.clientId,load,{immediate:true});onBeforeUnmount(()=>{seq++;});
</script>
<style scoped>.shared-files{background:white;padding:22px;border:1px solid #d7e3ef;border-radius:14px;margin:20px 0}.shared-files p{line-height:1.6}.shared-files article{display:flex;justify-content:space-between;align-items:center;gap:15px;border-top:1px solid #d7e3ef;padding:14px 0}.shared-files small{display:block;margin-top:5px;color:#526784}.shared-files button{font:inherit;border:1px solid #bbcede;background:white;color:#16457c;padding:10px;border-radius:8px;cursor:pointer}[role=alert]{color:#a12727}</style>
